/**
 * Jinx Lil' Monsta + Poppy Grower: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * Wiki: https://wiki.bloodontheclocktower.com/Poppy_Grower
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L116). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { reminderTargetMisses } from '#lib/core/rules/reminder-targets.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { babysitter, scriptOf, withLilMonsta } from './lilmonsta.test-support.ts';

describe("Lil' Monsta + Poppy Grower jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lilmonsta', 'poppygrower');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(data.byId.get('poppygrower')?.name).toBe('Poppy Grower');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lilmonsta', 'poppygrower'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['poppygrower'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: while the Poppy Grower lives the Minions don't learn each other,
	// so they wake one at a time until one takes the token, and the babysitter is a Minion. The
	// board fades every other player for Lil' Monsta's Is The Demon and warns if it goes on one
	// (warn, never lock).
	describe('while the Poppy Grower lives, a Minion takes the Lil’ Monsta token', () => {
		const cast = ['poppygrower', 'poisoner', 'widow', 'chef', 'empath', 'monk'];
		const base = withLilMonsta(cast);
		const misses = (s: typeof base, on: string) =>
			reminderTargetMisses(s.game, babysitter, s.seat(on), s.characters);

		it("is data in Lil' Monsta's rules", () => {
			expect(jinxRulesBetween('lilmonsta', 'poppygrower', committedCharacters())).toEqual({
				carriedBy: { type: 'minion', when: ['partner-alive'] },
				wakes: { how: 'one-by-one', when: ['partner-alive'] }
			});
		});

		it('fits only the Minions while the Poppy Grower is alive', () => {
			// Wiki: "If Lil' Monsta & the Poppy Grower are alive, Minions wake one by one, until one of
			// them chooses to take the Lil' Monsta token."
			expect(misses(base, 'poisoner')).toEqual([]);
			expect(misses(base, 'widow')).toEqual([]);
			expect(misses(base, 'chef')).toEqual(['jinx']);
			expect(misses(base, 'poppygrower')).toEqual(['jinx']);
		});

		it('fits anyone again once the Poppy Grower is dead', () => {
			// Wiki: "If Lil' Monsta & the Poppy Grower are alive, Minions wake one by one, until one of
			// them chooses to take the Lil' Monsta token."
			const dead = base.dies('poppygrower');
			expect(misses(dead, 'chef')).toEqual([]);
		});

		it('does not apply with no Poppy Grower on the script', () => {
			const others = ['poisoner', 'widow', 'chef', 'empath', 'monk'];
			const plain = scenario(others, { script: scriptOf([...others, 'lilmonsta']) });
			expect(misses(plain, 'chef')).toEqual([]);
		});
	});

	// Both pages' Related Jinxes: with the Poppy Grower alive the Minions can't wake together, as
	// that would show them each other, so they wake singly until one takes Lil' Monsta. Lil'
	// Monsta's step says so, about the Poppy Grower's player.
	describe('while the Poppy Grower lives, the Minions wake one at a time', () => {
		const cast = ['poppygrower', 'poisoner', 'widow', 'chef', 'empath', 'monk'];
		const base = withLilMonsta(cast);
		const oneByOne = (s: typeof base) =>
			nightStepAlerts(s.game, 'lilmonsta', s.characters).filter(
				(a) => a.kind === 'wakes-one-by-one'
			);

		it("is a wakes-one-by-one alert at Lil' Monsta's step", () => {
			// Wiki: "If Lil' Monsta & the Poppy Grower are alive, Minions wake one by one, until one of
			// them chooses to take the Lil' Monsta token."
			expect(oneByOne(base)).toEqual([
				expect.objectContaining({
					seatId: base.seat('poppygrower'),
					source: { characterId: 'lilmonsta' },
					partner: 'poppygrower',
					type: 'minion',
					wiki: 'https://wiki.bloodontheclocktower.com/Poppy_Grower#Related_Jinxes'
				})
			]);
		});

		it('is gone once the Poppy Grower is dead, so the Minions wake together', () => {
			// Wiki: "If Lil' Monsta & the Poppy Grower are alive, Minions wake one by one, until one of
			// them chooses to take the Lil' Monsta token."
			expect(oneByOne(base.dies('poppygrower'))).toEqual([]);
		});

		it('does not apply with no Poppy Grower on the script', () => {
			const others = ['poisoner', 'widow', 'chef', 'empath', 'monk'];
			const plain = scenario(others, { script: scriptOf([...others, 'lilmonsta']) });
			expect(oneByOne(plain)).toEqual([]);
		});
	});
});
